{
  "name": "DAQmx看门狗任务",
  "name_en": "DAQmx Watchdog Task",
  "manufacturer": "National Instruments (NI)",
  "description": "这是一个非物理的软件任务对象，用于为 NI DAQmx 看门狗任务配置超时时间、过期触发条件，以及模拟输出、数字输出和计数器通道的过期状态。它通常用于 DAQ 设备或机箱的安全保护，在主机失联或看门狗超时时将相关通道切换到预设安全状态。",
  "description_en": "This is a non-physical software task object for configuring an NI-DAQmx watchdog task, including timeout, expiration trigger conditions, and expiration states for analog output, digital output, and counter channels. It is typically used for safety protection on DAQ hardware or chassis, placing channels into predefined safe states when host communication is lost or the watchdog times out.",
  "tag_hints": [
    "NI-DAQmx",
    "watchdog timer",
    "DAQ safety",
    "expiration states",
    "network connection loss",
    "digital trigger"
  ],
  "actions": [
    {
      "action_name": "auto-expir_trig_dig_edge_edge",
      "description": "获取/设置数字边沿过期触发的触发边沿。",
      "description_en": "Get/set the trigger edge for the digital-edge expiration trigger."
    },
    {
      "action_name": "auto-expir_trig_dig_edge_src",
      "description": "获取/设置数字边沿过期触发源端子名称。",
      "description_en": "Get/set the source terminal name for the digital-edge expiration trigger."
    },
    {
      "action_name": "auto-expir_trig_trig_on_network_conn_loss",
      "description": "获取/设置网络连接丢失时是否触发看门狗过期。",
      "description_en": "Get/set whether watchdog expiration is triggered on network connection loss."
    },
    {
      "action_name": "auto-expir_trig_trig_type",
      "description": "获取/设置过期触发类型。",
      "description_en": "Get/set the expiration trigger type."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置看门狗超时时间。",
      "description_en": "Get/set the watchdog timeout."
    },
    {
      "action_name": "auto-cfg_watchdog_ao_expir_states",
      "description": "配置看门狗任务的模拟输出过期状态。",
      "description_en": "Configure the analog output expiration states for the watchdog task."
    },
    {
      "action_name": "auto-cfg_watchdog_co_expir_states",
      "description": "配置看门狗任务的计数器过期状态。",
      "description_en": "Configure the counter expiration states for the watchdog task."
    },
    {
      "action_name": "auto-cfg_watchdog_do_expir_states",
      "description": "配置看门狗任务的数字输出过期状态。",
      "description_en": "Configure the digital output expiration states for the watchdog task."
    },
    {
      "action_name": "auto-clear_expiration",
      "description": "清除看门狗过期状态并解锁设备。",
      "description_en": "Clear the watchdog expiration state and unlock the device."
    },
    {
      "action_name": "auto-close",
      "description": "关闭并清除此任务，释放占用资源。",
      "description_en": "Close and clear the task, releasing reserved resources."
    },
    {
      "action_name": "auto-control",
      "description": "按指定动作改变任务状态。",
      "description_en": "Change the task state according to the specified action."
    },
    {
      "action_name": "auto-reset_timer",
      "description": "重置看门狗内部计时器以防止超时。",
      "description_en": "Reset the internal watchdog timer to prevent timeout."
    },
    {
      "action_name": "auto-start",
      "description": "启动看门狗任务。",
      "description_en": "Start the watchdog task."
    },
    {
      "action_name": "auto-stop",
      "description": "停止看门狗任务。",
      "description_en": "Stop the watchdog task."
    }
  ]
}

